<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main" class="page">
    <section class="hero" aria-labelledby="page-title">
      <div class="hero-copy">
        <p class="eyebrow">Support</p>
        <h1 id="page-title">Contact our support team</h1>
        <p class="lede">
          Send us your details and we’ll get back to you as soon as we can.
          Full name and email are required. Phone number is optional.
        </p>
      </div>

      <div class="panel">
        <div class="form-header">
          <h2>Request help</h2>
          <p>Fields marked with <span aria-hidden="true" class="required-marker">*</span> are required.</p>
        </div>

        <form id="contact-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            >
            <p class="error-text" id="full-name-error" hidden>Error: Enter your full name.</p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required-marker" aria-hidden="true">*</span></label>
            <input
              id="email-address"
              name="email"
              type="email"
              autocomplete="email"
              required
              aria-describedby="email-address-help email-address-error"
            >
            <p class="help-text" id="email-address-help">We’ll use this to reply to your request.</p>
            <p class="error-text" id="email-address-error" hidden>Error: Enter a valid email address like name@example.com.</p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number <span class="optional-text">(optional)</span></label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              aria-describedby="phone-number-help phone-number-error"
            >
            <p class="help-text" id="phone-number-help">Use a format like +1 555 123 4567 or (555) 123-4567.</p>
            <p class="error-text" id="phone-number-error" hidden>Error: Enter a phone number in a valid format, or leave this field blank.</p>
          </div>

          <div class="actions">
            <button type="submit">Send message</button>
            <p class="status" id="form-status" role="status" aria-live="polite" hidden></p>
          </div>
        </form>
      </div>
    </section>
  </main>

  <script>
    const form = document.getElementById('contact-form');
    const statusEl = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          return value.trim().length > 0;
        },
        message: 'Error: Enter your full name.'
      },
      email: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate(value) {
          return value.trim().length > 0 && this.input.validity.valid;
        },
        message: 'Error: Enter a valid email address like name@example.com.'
      },
      phone: {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) return true;
          return /^[+()\d\s.-]{7,}$/.test(trimmed) && /\d/.test(trimmed);
        },
        message: 'Error: Enter a phone number in a valid format, or leave this field blank.'
      }
    };

    const touched = new Set();

    function setFieldState(field, isValid) {
      if (isValid) {
        field.input.removeAttribute('aria-invalid');
        field.error.hidden = true;
        field.error.textContent = '';
        return;
      }

      field.input.setAttribute('aria-invalid', 'true');
      field.error.hidden = false;
      field.error.textContent = field.message;
    }

    function validateField(key, showTouched = false) {
      const field = fields[key];
      const isValid = field.validate(field.input.value);

      if (showTouched || touched.has(key) || !isValid) {
        setFieldState(field, isValid);
      }

      return isValid;
    }

    Object.entries(fields).forEach(([key, field]) => {
      const markTouched = () => {
        touched.add(key);
        validateField(key, true);
      };

      field.input.addEventListener('blur', markTouched);
      field.input.addEventListener('input', () => {
        if (touched.has(key)) {
          validateField(key, true);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const order = ['fullName', 'email', 'phone'];
      const invalidKey = order.find((key) => !validateField(key, true));

      if (invalidKey) {
        const firstInvalid = fields[invalidKey].input;
        firstInvalid.focus();
        firstInvalid.scrollIntoView({ block: 'center', behavior: 'smooth' });
        statusEl.hidden = true;
        return;
      }

      statusEl.textContent = 'Your message is ready to send.';
      statusEl.hidden = false;
      form.reset();

      Object.values(fields).forEach((field) => {
        field.input.removeAttribute('aria-invalid');
        field.error.hidden = true;
        field.error.textContent = '';
      });
      touched.clear();
    });
  </script>
</body>
