338.             <label for="email-address">Email address <span class="required-marker" aria-hidden="true">*</span></label>
339.             <input
340.               id="email-address"
341.               name="email"
342.               type="email"
343.               autocomplete="email"
344.               required
345.               aria-describedby="email-address-help email-address-error"
346.             >
