348.             <p class="error-text" id="email-address-error" hidden>Error: Enter a valid email address like name@example.com.</p>
349.           </div>
350. 
351.           <div class="form-field">
352.             <label for="phone-number">Phone number <span class="optional-text">(optional)</span></label>
353.             <input
354.               id="phone-number"
355.               name="phone"
356.               type="tel"
357.               inputmode="tel"
358.               autocomplete="tel"
359.               aria-describedby="phone-number-help phone-number-error"
360.             >
361.             <p class="help-text" id="phone-number-help">Use a format like +1 555 123 4567 or (555) 123-4567.</p>
362.             <p class="error-text" id="phone-number-error" hidden>Error: Enter a phone number in a valid format, or leave this field blank.</p>
363.           </div>
