374.   <script>
375.     const form = document.getElementById('contact-form');
376.     const statusEl = document.getElementById('form-status');
377. 
378.     const fields = {
379.       fullName: {
380.         input: document.getElementById('full-name'),
381.         error: document.getElementById('full-name-error'),
382.         validate(value) {
383.           return value.trim().length > 0;
384.         },
385.         message: 'Error: Enter your full name.'
386.       },
387.       email: {
388.         input: document.getElementById('email-address'),
389.         error: document.getElementById('email-address-error'),
390.         validate(value) {
391.           return value.trim().length > 0 && this.input.validity.valid;
392.         },
393.         message: 'Error: Enter a valid email address like name@example.com.'
394.       },
395.       phone: {
396.         input: document.getElementById('phone-number'),
397.         error: document.getElementById('phone-number-error'),
398.         validate(value) {
399.           const trimmed = value.trim();
400.           if (!trimmed) return true;
401.           return /^[+()\d\s.-]{7,}$/.test(trimmed) && /\d/.test(trimmed);
402.         },
403.         message: 'Error: Enter a phone number in a valid format, or leave this field blank.'
404.       }
405.     };
406. 
407.     const touched = new Set();
408. 
409.     function setFieldState(field, isValid) {
410.       if (isValid) {
411.         field.input.removeAttribute('aria-invalid');
412.         field.error.hidden = true;
413.         field.error.textContent = '';
414.         return;
415.       }
416. 
417.       field.input.setAttribute('aria-invalid', 'true');
418.       field.error.hidden = false;
419.       field.error.textContent = field.message;
420.     }
421. 
422.     function validateField(key, showTouched = false) {
423.       const field = fields[key];
424.       const isValid = field.validate(field.input.value);
425. 
426.       if (showTouched || touched.has(key) || !isValid) {
427.         setFieldState(field, isValid);
428.       }
429. 
430.       return isValid;
431.     }
432. 
433.     Object.entries(fields).forEach(([key, field]) => {
434.       const markTouched = () => {
435.         touched.add(key);
436.         validateField(key, true);
437.       };
438. 
439.       field.input.addEventListener('blur', markTouched);
440.       field.input.addEventListener('input', () => {
441.         if (touched.has(key)) {
442.           validateField(key, true);
443.         }
444.       });
445.     });
446. 
447.     form.addEventListener('submit', (event) => {
448.       event.preventDefault();
449. 
450.       const order = ['fullName', 'email', 'phone'];
451.       const invalidKey = order.find((key) => !validateField(key, true));
452. 
453.       if (invalidKey) {
454.         const firstInvalid = fields[invalidKey].input;
455.         firstInvalid.focus();
456.         firstInvalid.scrollIntoView({ block: 'center', behavior: 'smooth' });
457.         statusEl.hidden = true;
458.         return;
459.       }
460. 
461.       statusEl.textContent = 'Your message is ready to send.';
462.       statusEl.hidden = false;
463.       form.reset();
464. 
465.       Object.values(fields).forEach((field) => {
466.         field.input.removeAttribute('aria-invalid');
467.         field.error.hidden = true;
468.         field.error.textContent = '';
469.       });
470.       touched.clear();
471.     });
472.   </script>
